INSERT INTO picture360_images (examId, specialty, conditionName, imageUrl, keyFeatures, examPearl, optionA, optionB, optionC, optionD, correctAnswer, explanation, status) VALUES
(1, 'Ophthalmology', 'Optic Neuritis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_optic-neuritis-placeholder.webp', 'Acute unilateral painful visual loss; pain on eye movement; relative afferent pupillary defect (RAPD); reduced colour vision (red desaturation); central scotoma; optic disc may appear swollen or normal (retrobulbar neuritis)', 'Optic neuritis is strongly associated with multiple sclerosis — up to 50% of patients develop MS within 15 years. MRI brain should be performed. IV methylprednisolone speeds recovery but does not alter final visual outcome. Bilateral optic neuritis in a child suggests neuromyelitis optica', 'Inflammatory demyelination of the optic nerve associated with MS', 'Central retinal artery occlusion', 'Acute angle-closure glaucoma', 'Anterior ischaemic optic neuropathy', 'A', 'Optic neuritis is inflammation of the optic nerve, most commonly due to demyelination. It presents with acute unilateral painful visual loss, pain on eye movement, RAPD, and impaired colour vision. It is strongly associated with multiple sclerosis. MRI brain should be performed to assess for demyelinating lesions. IV methylprednisolone accelerates visual recovery but does not change the final visual outcome. Most patients recover good vision within weeks.', 'active'),
(1, 'Ophthalmology', 'Retinitis Pigmentosa', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_retinitis-pigmentosa-placeholder.webp', 'Bone-spicule pigmentation in the mid-peripheral retina; arteriolar attenuation; waxy pallor of the optic disc; progressive night blindness (nyctalopia); tunnel vision from concentric visual field loss; bilateral and symmetrical', 'Retinitis pigmentosa is the most common inherited retinal dystrophy. It causes progressive rod photoreceptor degeneration leading to night blindness followed by peripheral field loss. Electroretinography (ERG) shows reduced or absent rod responses. Associated with Usher syndrome (RP + sensorineural deafness)', 'Inherited retinal dystrophy with progressive rod photoreceptor degeneration', 'Diabetic retinopathy with peripheral ischaemia', 'Choroidal melanoma', 'Retinal detachment', 'A', 'Retinitis pigmentosa is a group of inherited retinal dystrophies characterised by progressive degeneration of rod photoreceptors. It presents with night blindness (nyctalopia) followed by progressive peripheral visual field loss (tunnel vision). Fundoscopy shows bone-spicule pigmentation, arteriolar attenuation, and waxy disc pallor. ERG confirms the diagnosis. There is no curative treatment; management includes low vision aids and genetic counselling. It may be associated with Usher syndrome.', 'active'),
(1, 'Ophthalmology', 'Blepharitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_blepharitis-placeholder.webp', 'Red inflamed eyelid margins; crusting and scaling at the base of the eyelashes; collarettes around lash bases; meibomian gland dysfunction with blocked orifices; bilateral; chronic with exacerbations and remissions', 'Blepharitis is classified as anterior (staphylococcal or seborrhoeic, affecting lash bases) or posterior (meibomian gland dysfunction). Management is lid hygiene: warm compresses, lid massage, and lid scrubs. It is the most common cause of chronic eye irritation in primary care', 'Chronic inflammation of the eyelid margins', 'Bacterial conjunctivitis', 'Orbital cellulitis', 'Chalazion', 'A', 'Blepharitis is chronic inflammation of the eyelid margins, classified as anterior (staphylococcal or seborrhoeic) or posterior (meibomian gland dysfunction). It presents with red, irritated eyelid margins with crusting and scaling. Management centres on lid hygiene: warm compresses for 5-10 minutes, lid massage to express meibomian glands, and lid scrubs with dilute baby shampoo or commercial lid wipes. It is a chronic condition requiring ongoing maintenance.', 'active'),
(1, 'Ophthalmology', 'Dacryocystitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_dacryocystitis-placeholder.webp', 'Painful erythematous swelling over the medial canthus and lacrimal sac area; epiphora (watering eye); purulent discharge may be expressible from the punctum on pressure over the lacrimal sac; may progress to preseptal cellulitis', 'Acute dacryocystitis is infection of the lacrimal sac, usually secondary to nasolacrimal duct obstruction. Oral co-amoxiclav is first-line. Dacryocystorhinostomy (DCR) is the definitive surgical treatment for recurrent dacryocystitis. In neonates, congenital nasolacrimal duct obstruction usually resolves spontaneously by 12 months', 'Infection of the lacrimal sac from nasolacrimal duct obstruction', 'Preseptal cellulitis from sinusitis', 'Chalazion of the lower eyelid', 'Orbital tumour', 'A', 'Dacryocystitis is infection of the lacrimal sac, usually secondary to nasolacrimal duct obstruction. It presents with a painful red swelling at the medial canthus with epiphora and purulent discharge. Acute dacryocystitis is treated with oral antibiotics (co-amoxiclav). Dacryocystorhinostomy (DCR) is the definitive surgical treatment for recurrent episodes. Congenital nasolacrimal duct obstruction in neonates usually resolves spontaneously by 12 months with conservative management.', 'active'),
(1, 'Ophthalmology', 'Periorbital Cellulitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_periorbital-cellulitis-placeholder.webp', 'Erythema and oedema of the eyelid and periorbital skin; eye movements are full and painless; visual acuity is normal; no proptosis; the eye itself is not involved; may follow insect bite, trauma, or upper respiratory infection', 'Periorbital (preseptal) cellulitis must be distinguished from orbital (postseptal) cellulitis. Key differentiators: orbital cellulitis causes painful restricted eye movements, proptosis, reduced visual acuity, and RAPD. Periorbital cellulitis is treated with oral antibiotics; orbital cellulitis requires IV antibiotics and urgent CT imaging', 'Preseptal soft tissue infection anterior to the orbital septum', 'Orbital cellulitis with postseptal infection', 'Allergic periorbital oedema', 'Nephrotic syndrome with periorbital oedema', 'A', 'Periorbital (preseptal) cellulitis is infection of the eyelid and periorbital tissues anterior to the orbital septum. Eye movements are full and painless, visual acuity is normal, and there is no proptosis. It is usually caused by skin flora following trauma or insect bites. Treatment is oral co-amoxiclav. It must be distinguished from orbital cellulitis, which involves painful restricted eye movements, proptosis, and visual compromise requiring IV antibiotics and CT imaging.', 'active'),
(1, 'Ophthalmology', 'Orbital Cellulitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_orbital-cellulitis-placeholder.webp', 'Proptosis; painful restricted eye movements (ophthalmoplegia); reduced visual acuity; periorbital erythema and oedema; relative afferent pupillary defect may be present; systemic features with fever; often secondary to sinusitis', 'Orbital cellulitis is a sight-threatening and potentially life-threatening emergency. It is most commonly secondary to ethmoid sinusitis. Urgent CT orbits and sinuses is required. Treatment is IV broad-spectrum antibiotics. Complications include subperiosteal abscess, cavernous sinus thrombosis, intracranial abscess, and permanent visual loss', 'Postseptal infection of the orbit, usually secondary to sinusitis', 'Periorbital cellulitis from insect bite', 'Thyroid eye disease with proptosis', 'Orbital lymphoma', 'A', 'Orbital (postseptal) cellulitis is infection posterior to the orbital septum, most commonly secondary to ethmoid sinusitis. It presents with proptosis, painful restricted eye movements, reduced visual acuity, and systemic features. It is an ophthalmic emergency. Urgent CT orbits and sinuses is required to assess for subperiosteal abscess. Treatment is IV broad-spectrum antibiotics. Surgical drainage may be needed for abscess formation. Complications include cavernous sinus thrombosis and visual loss.', 'active'),
(1, 'Ophthalmology', 'Xanthelasma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_xanthelasma-placeholder.webp', 'Yellowish flat or slightly raised plaques on the medial aspect of the upper and lower eyelids; bilateral and symmetrical; soft and non-tender; may be associated with hyperlipidaemia but often occur with normal lipid levels', 'Xanthelasma palpebrarum is the most common cutaneous xanthoma. Approximately 50% of patients have underlying hyperlipidaemia — a fasting lipid profile should always be checked. Treatment is cosmetic: surgical excision, laser ablation, or trichloroacetic acid. Recurrence is common', 'Lipid deposits in the periorbital skin, check fasting lipid profile', 'Dermoid cyst of the eyelid', 'Sebaceous gland carcinoma', 'Basal cell carcinoma of the eyelid', 'A', 'Xanthelasma palpebrarum presents as yellowish plaques on the medial eyelids. It is the most common cutaneous xanthoma. Approximately 50% of patients have underlying hyperlipidaemia, so a fasting lipid profile should always be checked. Even with normal lipids, xanthelasma may indicate increased cardiovascular risk. Treatment is cosmetic and includes surgical excision, laser ablation, or chemical cautery. Recurrence after treatment is common.', 'active'),
(1, 'Ophthalmology', 'Entropion', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_entropion-placeholder.webp', 'Inward turning of the eyelid margin causing lashes to rub against the cornea; usually affects the lower eyelid; causes foreign body sensation, tearing, and corneal irritation; involutional (age-related) is the most common type', 'Involutional entropion is caused by horizontal lid laxity and overriding preseptal orbicularis. Corneal abrasion from lash contact can lead to corneal ulceration and visual loss. Temporary relief with taping; definitive treatment is surgical correction. Cicatricial entropion may be caused by trachoma, chemical burns, or Stevens-Johnson syndrome', 'Inward turning of the eyelid with lashes abrading the cornea', 'Ectropion with outward turning of the eyelid', 'Trichiasis with misdirected lashes', 'Blepharospasm', 'A', 'Entropion is inward turning of the eyelid margin, causing the lashes to rub against the cornea. The most common type is involutional (age-related), affecting the lower eyelid. It causes foreign body sensation, tearing, and risk of corneal abrasion and ulceration. Temporary management includes taping the lid or botulinum toxin injection. Definitive treatment is surgical correction. Cicatricial entropion may result from trachoma, chemical burns, or Stevens-Johnson syndrome.', 'active'),
(1, 'Ophthalmology', 'Ectropion', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_ectropion-placeholder.webp', 'Outward turning of the lower eyelid exposing the palpebral conjunctiva; epiphora (watering eye) due to malposition of the punctum; conjunctival injection and keratinisation; exposure keratopathy in severe cases', 'Involutional ectropion is the most common type, caused by age-related horizontal lid laxity. The punctum everts away from the globe causing epiphora. Chronic exposure leads to conjunctival keratinisation. Lubricating eye drops provide symptomatic relief; definitive treatment is surgical tightening of the lower lid', 'Outward turning of the eyelid causing exposure and epiphora', 'Entropion with inward turning of the eyelid', 'Facial nerve palsy causing lagophthalmos', 'Thyroid eye disease', 'A', 'Ectropion is outward turning of the eyelid, most commonly the lower lid. Involutional ectropion from age-related lid laxity is the most common type. It causes epiphora due to punctal malposition, conjunctival exposure and keratinisation, and risk of exposure keratopathy. Management includes lubricating eye drops for symptomatic relief and surgical correction (lateral tarsal strip procedure) for definitive treatment. Paralytic ectropion may occur in facial nerve palsy.', 'active'),
(1, 'Ophthalmology', 'Pinguecula', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_pinguecula-placeholder.webp', 'Yellowish elevated nodule on the bulbar conjunctiva adjacent to the limbus; does not extend onto the cornea; usually on the nasal side; bilateral; may become inflamed (pingueculitis)', 'A pinguecula is a degenerative condition of the conjunctiva caused by UV exposure, wind, and dust. It does NOT extend onto the cornea — if it does, it is a pterygium. No treatment is usually needed. Lubricating drops for irritation; short course of topical NSAIDs or mild steroids for pingueculitis', 'Conjunctival degeneration that does not extend onto the cornea', 'Pterygium extending onto the cornea', 'Conjunctival melanoma', 'Episcleritis', 'A', 'A pinguecula is a yellowish elevated lesion on the bulbar conjunctiva near the limbus, caused by chronic UV exposure and environmental irritation. It does not extend onto the cornea (distinguishing it from a pterygium). It is usually asymptomatic and requires no treatment. If inflamed (pingueculitis), lubricating drops or short-course topical NSAIDs may be used. Surgical excision is rarely indicated and only for cosmetic reasons or if it interferes with contact lens wear.', 'active'),
(1, 'Ophthalmology', 'Anisocoria', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_anisocoria-placeholder.webp', 'Unequal pupil sizes; may be physiological (up to 1mm difference in 20% of population) or pathological; assess in light and dark conditions to determine which pupil is abnormal; check for ptosis, eye movement restriction, and pain', 'To determine the abnormal pupil: if anisocoria is greater in the dark, the smaller pupil is abnormal (failure to dilate — Horner syndrome). If greater in the light, the larger pupil is abnormal (failure to constrict — third nerve palsy or pharmacological). Physiological anisocoria remains constant in all lighting', 'Unequal pupil size requiring assessment of sympathetic and parasympathetic pathways', 'Normal variant requiring no investigation', 'Bilateral mydriasis from drug use', 'Bilateral miosis from opioid use', 'A', 'Anisocoria is unequal pupil size. Physiological anisocoria (up to 1mm) occurs in 20% of the population and remains constant in all lighting conditions. Pathological causes include Horner syndrome (miosis, ptosis, anhidrosis — sympathetic pathway disruption), third nerve palsy (mydriasis, ptosis, eye down and out — parasympathetic pathway disruption), and pharmacological causes. Assessment in light and dark conditions determines which pupil is abnormal.', 'active'),
(1, 'Ophthalmology', 'Argyll Robertson Pupil', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_argyll-robertson-placeholder.webp', 'Small irregular pupils bilaterally; accommodate but do not react to light (light-near dissociation); associated with neurosyphilis; pupils are difficult to dilate pharmacologically', 'Argyll Robertson pupils are pathognomonic of neurosyphilis. The mnemonic is ARP — Accommodation Reflex Present (but light reflex absent). They are small, irregular, and bilateral. Other causes of light-near dissociation include diabetes and Parinaud syndrome, but these do not produce the classic small irregular pupils', 'Light-near dissociation pathognomonic of neurosyphilis', 'Holmes-Adie tonic pupil', 'Horner syndrome', 'Physiological anisocoria', 'A', 'Argyll Robertson pupils are bilateral small irregular pupils that accommodate but do not react to light (light-near dissociation). They are pathognomonic of neurosyphilis. The pupils are difficult to dilate with mydriatics. The lesion is in the pretectal area of the midbrain. Syphilis serology should be performed. Other causes of light-near dissociation include diabetes mellitus and dorsal midbrain lesions, but these do not produce the classic small irregular pupils of Argyll Robertson.', 'active'),
(1, 'Ophthalmology', 'Holmes-Adie Pupil', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_holmes-adie-placeholder.webp', 'Unilateral dilated pupil with sluggish or absent light response; slow tonic accommodation (vermiform movements of the iris on slit lamp); denervation supersensitivity to dilute pilocarpine (0.1%); typically affects young women', 'Holmes-Adie tonic pupil is caused by damage to the ciliary ganglion or short ciliary nerves. It is benign. The pupil is large and reacts sluggishly to light but shows tonic near response. Denervation supersensitivity to dilute pilocarpine (0.1%) confirms the diagnosis. Holmes-Adie syndrome includes absent deep tendon reflexes', 'Benign tonic pupil from ciliary ganglion denervation', 'Third nerve palsy', 'Pharmacological mydriasis from tropicamide', 'Traumatic mydriasis', 'A', 'Holmes-Adie tonic pupil is a benign condition caused by denervation of the ciliary ganglion or short ciliary nerves. It presents with a unilateral dilated pupil that reacts sluggishly to light but shows slow tonic accommodation. It typically affects young women. Denervation supersensitivity to dilute pilocarpine (0.1%) confirms the diagnosis. Holmes-Adie syndrome combines the tonic pupil with absent deep tendon reflexes. No treatment is required; reassurance is the main management.', 'active'),
(1, 'Ophthalmology', 'Leukocoria', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_leukocoria-placeholder.webp', 'White pupillary reflex instead of the normal red reflex; may be noticed by parents in photographs; unilateral or bilateral; requires urgent ophthalmological assessment to exclude retinoblastoma', 'Leukocoria (white pupil) in a child is retinoblastoma until proven otherwise. Other causes include congenital cataract, retinopathy of prematurity, persistent fetal vasculature, Coats disease, and toxocariasis. All newborns should have a red reflex check as part of the newborn examination', 'Absent red reflex requiring urgent assessment to exclude retinoblastoma', 'Normal variant in flash photography', 'Congenital glaucoma', 'Albinism', 'A', 'Leukocoria is a white pupillary reflex, most commonly noticed by parents in photographs. In a child, the most important diagnosis to exclude is retinoblastoma, the most common primary intraocular malignancy of childhood. Other causes include congenital cataract, retinopathy of prematurity, persistent fetal vasculature, and Coats disease. Urgent ophthalmological referral is mandatory. All newborns should have a red reflex check as part of the routine newborn examination.', 'active'),
(1, 'Ophthalmology', 'Nystagmus', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_nystagmus-placeholder.webp', 'Involuntary rhythmic oscillation of the eyes; may be horizontal, vertical, rotatory, or mixed; jerk nystagmus has fast and slow phases; direction defined by the fast phase; may be congenital or acquired', 'The direction of jerk nystagmus is named by the fast phase. Cerebellar lesions cause nystagmus towards the side of the lesion. Downbeat nystagmus suggests a lesion at the craniocervical junction (e.g. Arnold-Chiari malformation). Drug-induced nystagmus (phenytoin, carbamazepine, alcohol) is common and usually horizontal', 'Involuntary eye oscillation indicating vestibular or cerebellar pathology', 'Normal physiological eye movement', 'Voluntary eye movement disorder', 'Tic disorder', 'A', 'Nystagmus is involuntary rhythmic oscillation of the eyes. Jerk nystagmus has a slow drift and fast corrective saccade; the direction is named by the fast phase. Causes include vestibular disorders (peripheral or central), cerebellar disease, brainstem lesions, drugs (phenytoin, carbamazepine, alcohol), and congenital forms. Downbeat nystagmus suggests a craniocervical junction lesion. Assessment includes direction, gaze-evoked patterns, and associated neurological signs to localise the lesion.', 'active'),
(1, 'Ophthalmology', 'Trachoma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_trachoma-placeholder.webp', 'Follicular conjunctivitis of the upper tarsal conjunctiva; Herbert pits (limbal follicles that resolve leaving depressions); pannus formation (corneal vascularisation); cicatricial entropion and trichiasis in chronic disease; leading infectious cause of blindness worldwide', 'Trachoma is caused by Chlamydia trachomatis (serotypes A-C). WHO SAFE strategy: Surgery for trichiasis, Antibiotics (azithromycin), Facial cleanliness, Environmental improvement. It is the leading infectious cause of preventable blindness globally. Repeated infection leads to conjunctival scarring, entropion, trichiasis, and corneal opacification', 'Chlamydial conjunctivitis causing scarring and preventable blindness', 'Viral conjunctivitis from adenovirus', 'Allergic conjunctivitis', 'Bacterial conjunctivitis from Staphylococcus', 'A', 'Trachoma is a chronic keratoconjunctivitis caused by Chlamydia trachomatis (serotypes A-C). It is the leading infectious cause of preventable blindness worldwide. Repeated infection causes conjunctival scarring, entropion, trichiasis, and corneal opacification. The WHO SAFE strategy includes Surgery for trichiasis, Antibiotics (single-dose azithromycin), Facial cleanliness, and Environmental improvement. Active trachoma is characterised by follicles on the upper tarsal conjunctiva.', 'active'),
(1, 'Ophthalmology', 'Coloboma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_coloboma-placeholder.webp', 'Keyhole-shaped defect in the iris, typically inferonasally; may also affect the choroid, retina, or optic disc; congenital; results from failure of closure of the embryonic fissure; may be unilateral or bilateral', 'Iris coloboma results from incomplete closure of the embryonic (choroidal) fissure during the 5th-7th week of gestation. It is typically inferonasal. It may be isolated or part of CHARGE syndrome (Coloboma, Heart defects, Atresia choanae, Retardation of growth, Genital abnormalities, Ear abnormalities). Choroidal coloboma may cause visual field defects', 'Congenital defect from failure of embryonic fissure closure', 'Traumatic iris tear', 'Surgical iridectomy', 'Iris melanoma', 'A', 'Coloboma is a congenital defect resulting from incomplete closure of the embryonic (choroidal) fissure during weeks 5-7 of gestation. It typically presents as a keyhole-shaped defect in the iris, located inferonasally. It may also involve the choroid, retina, lens, or optic disc. It may be isolated or part of CHARGE syndrome. Visual significance depends on the structures involved — choroidal and optic disc colobomas may cause significant visual impairment. Genetic counselling may be appropriate.', 'active'),
(1, 'Ophthalmology', 'Trichiasis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_trichiasis-placeholder.webp', 'Misdirected eyelashes growing inward toward the globe; causes corneal irritation, foreign body sensation, and tearing; may lead to corneal abrasion and ulceration; eyelid position is normal (distinguishing it from entropion)', 'Trichiasis is misdirected lashes with a normally positioned lid margin — this distinguishes it from entropion where the entire lid turns inward. Causes include chronic blepharitis, trachoma, chemical burns, and Stevens-Johnson syndrome. Treatment includes epilation (temporary), electrolysis, cryotherapy, or surgical lash follicle destruction', 'Misdirected lashes abrading the cornea with normal lid position', 'Entropion with inward turning of the eyelid', 'Distichiasis with an extra row of lashes', 'Blepharitis', 'A', 'Trichiasis is misdirection of eyelashes toward the globe with a normally positioned eyelid margin. This distinguishes it from entropion, where the entire lid margin turns inward. It causes corneal irritation, foreign body sensation, and risk of corneal abrasion and ulceration. Causes include chronic blepharitis, trachoma, chemical burns, and cicatricial conditions. Treatment includes epilation (temporary relief), electrolysis, cryotherapy, or surgical destruction of the lash follicles.', 'active'),
(1, 'Ophthalmology', 'Strabismus', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_strabismus-placeholder.webp', 'Misalignment of the visual axes; esotropia (convergent squint) or exotropia (divergent squint); detected by corneal light reflex test and cover test; may be constant or intermittent; in children may lead to amblyopia', 'New-onset squint in a child over 6 months requires urgent assessment to exclude retinoblastoma or other serious pathology. Constant esotropia at any age is abnormal. Intermittent exotropia may be normal in neonates up to 3 months. Cover test is the gold standard for detecting strabismus. Early treatment prevents amblyopia', 'Ocular misalignment requiring assessment for amblyopia risk', 'Normal intermittent eye movement in infants', 'Nystagmus', 'Convergence insufficiency only', 'A', 'Strabismus (squint) is misalignment of the visual axes. Esotropia (convergent) is more common in children; exotropia (divergent) is more common in adults. Detection is by corneal light reflex test and cover/uncover test. In children, strabismus can cause amblyopia if untreated, as the brain suppresses the image from the deviating eye. New-onset squint after 6 months of age requires urgent referral to exclude serious pathology. Treatment includes correcting refractive error, occlusion therapy, and surgery.', 'active'),
(1, 'Ophthalmology', 'Amblyopia', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ophthalmology_amblyopia-placeholder.webp', 'Reduced best-corrected visual acuity in one or both eyes without detectable organic pathology; caused by abnormal visual development during the critical period (birth to approximately 7-8 years); most common cause of monocular visual impairment in children', 'Amblyopia develops during the critical period of visual development. Causes: strabismus (most common), anisometropia (unequal refractive error), and stimulus deprivation (e.g. congenital cataract). Treatment is correction of the underlying cause plus occlusion therapy (patching the good eye) to force use of the amblyopic eye. Treatment is most effective before age 7', 'Reduced vision from abnormal visual development in childhood', 'Optic nerve hypoplasia', 'Retinal dystrophy', 'Cortical visual impairment', 'A', 'Amblyopia (lazy eye) is reduced best-corrected visual acuity in one or both eyes due to abnormal visual development during the critical period (birth to approximately 7-8 years). It is the most common cause of monocular visual impairment in children. Causes include strabismus, anisometropia, and stimulus deprivation. Treatment involves correcting the underlying cause and occlusion therapy (patching the better eye). Treatment is most effective before age 7, with diminishing response after this age.', 'active');
